/* DOM integration checks. Pass an isolated fixture JSON generated by TestClient.
 * Run with jsdom available on NODE_PATH; this does not launch a browser. */
const {JSDOM, VirtualConsole} = require('jsdom');
const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');
const root = path.resolve(__dirname, '../static');
const fixture = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const tick = () => new Promise(resolve => setTimeout(resolve, 0));

async function build(role) {
  const errors = [], calls = [], vc = new VirtualConsole();
  vc.on('jsdomError', error => errors.push(error.message));
  const dom = new JSDOM('<div id="app"></div><div id="toast"></div><div id="modal-root"></div>', {
    url:'http://localhost', runScripts:'dangerously', virtualConsole:vc
  });
  const w = dom.window, state = structuredClone(fixture[role]);
  w.scrollTo = () => {};
  w.confirm = () => true;
  if(role !== 'demo') w.localStorage.setItem('haru_token', 'unit-test');
  w.fetch = async (url, options={}) => {
    calls.push({url, options});
    let data = url === '/api/state' ? state : url === '/api/demo' ? fixture.demo :
      url.startsWith('/api/history/') ? fixture.history :
      url.startsWith('/api/admin/student/') ? fixture.preview :
      {ok:true, status:'offline', message:'isolated test'};
    if(url === '/api/admin/advance') {
      state.room.day++;
      data = {ok:true, day:state.room.day, phase:'trading'};
    }
    return {ok:true, json:async () => structuredClone(data)};
  };
  for(const name of ['core.js','guides.js','research.js']) {
    const script = w.document.createElement('script');
    script.textContent = fs.readFileSync(path.join(root,name), 'utf8');
    w.document.body.appendChild(script);
  }
  await tick();
  return {dom,w,errors,calls};
}

(async () => {
  for(const role of ['student','teacher']) {
    const {dom,w,errors,calls} = await build(role);
    const d = w.document;
    const mainLabels = [...d.querySelectorAll('.side-nav .nav-text')].map(n=>n.textContent);
    assert.deepEqual(mainLabels, role==='student' ?
      ['오늘의 소식','투자하기','내 자산','투자 기록'] : ['수업 진행','학생 현황','운영 설정']);
    const destinations = role==='student' ?
      ['home','news','earnings','market','portfolio','journal','bank','orders'] :
      ['home','news','earnings','market','players','orders','admin'];
    for(const destination of destinations) {
      w.go(destination);
      assert.ok(d.querySelector('#page').innerHTML.length>100, role+' '+destination);
      assert.ok(!/NaN|undefined/.test(d.querySelector('#page').textContent), role+' '+destination+' invalid output');
      assert.equal(d.querySelectorAll('.side-nav button.active').length,1);
    }
    await w.detail('HBEL');
    assert.equal(d.querySelector('.company-tabs button.active').textContent,'뉴스·사업');
    d.querySelector('#qty').value='3';
    d.querySelector('#reason').value='같은 기업의 실적을 더 확인하겠다';
    w.updateOrderTotal();
    const firstEvidence=d.querySelector('#trade-evidence input');
    firstEvidence.checked=true;
    d.querySelectorAll('.company-tabs button')[1].click();
    assert.equal(d.querySelector('#reason').value,'같은 기업의 실적을 더 확인하겠다');
    assert.equal(d.querySelector('#qty').value,'3');
    assert.ok(d.querySelector('#trade-evidence input').checked);
    assert.equal(d.querySelectorAll('.main-financials>.financial-tile').length,3);
    assert.equal(w.quoteFee(10000),2);
    assert.equal(w.quoteFee(100000),15);
    assert.equal(w.quoteFee(1),1);
    w.orderSide('sell');
    assert.equal(d.querySelector('#settlementLabel').textContent,'받을 금액');
    assert.equal(d.querySelector('.trade-submit').textContent,'매도하고 이유 저장');
    assert.ok(d.querySelector('.fee-disclosure').textContent.includes('0.015%'));
    if(role==='student') {
      w.eval('S.player.day_ready=true;render()');
      assert.equal(d.querySelector('.trade-submit').disabled,false);
      let confirmation='';w.confirm=message=>{confirmation=message;return false};
      await w.place();
      assert.ok(confirmation.includes('수수료 (0.015%)'));
      assert.ok(confirmation.includes('받을 금액'));
      w.go('journal');
      assert.equal(d.querySelectorAll('.note-card').length,1, 'linked trade appears once');
      assert.ok(d.querySelector('.record-trade-cost').textContent.includes('수수료'));
      assert.equal(d.querySelector('.note-composer'),null);
      w.openNoteComposer('HBEL');
      assert.ok(d.querySelector('#note-thesis'));
      w.go('news');
      assert.equal(d.querySelector('.advanced-filters'),null);
      w.eval('newsAdvanced=true;render()');
      assert.ok(d.querySelector('.advanced-filters'));
      assert.equal(d.querySelector('.guide-help').open,false);
      await w.openArticle(fixture.student.news[0].id);
      assert.ok(d.querySelector('[role="dialog"]'));
      w.closeModal();
    } else {
      assert.equal(d.querySelector('.trade-submit').disabled,true);
      w.go('home');
      await Promise.all([w.adminAction('advance'),w.adminAction('advance')]);
      assert.equal(calls.filter(c=>c.url==='/api/admin/advance').length,1);
      w.eval("tab='preview'");await w.loadPreview(fixture.teacher.participants[0].id);
      assert.equal(d.querySelectorAll('.preview-menu button').length,4);
      for(const destination of ['home','news','earnings','market','portfolio','journal','bank','orders']) {
        w.go(destination);
        assert.ok(d.querySelector('#page').innerHTML.length>100,'preview '+destination);
      }
      await w.detail('HBEL');
      assert.equal(d.querySelector('.trade-submit').disabled,true);
    }
    assert.deepEqual(errors,[],role+' script errors');
    console.log(role+': menus, analysis tabs, record links, fee display and access passed');
    dom.window.close();
  }
  const {dom,w,errors}=await build('demo');
  await w.startDemo();
  assert.equal(w.document.querySelectorAll('.side-nav button').length,4);
  await w.detail('HBEL');
  assert.equal(w.document.querySelector('.trade-submit').disabled,true);
  w.exitDemo();
  assert.ok(w.document.body.textContent.includes('학생 화면 미리 체험하기'));
  assert.deepEqual(errors,[]);
  dom.window.close();
  console.log('demo: read-only state and exit passed');
})().catch(error=>{console.error(error);process.exit(1)});
